insert into public.translation_dictionary(namespace,source_key,translations) values ('ui','AI Marketing Director','{"en":"AI Marketing Director","fr":"Directeur marketing IA"}'::jsonb),('ui','Give the director a mission. It prepares a campaign and scheduled drafts for review.','{"en":"Give the director a mission. It prepares a campaign and scheduled drafts for review.","fr":"Confiez une mission au directeur. Il prépare une campagne et des brouillons planifiés à valider."}'::jsonb),('ui','Marketing mission','{"en":"Marketing mission","fr":"Mission marketing"}'::jsonb),('ui','Promote a title, attract new members, or let the director identify opportunities.','{"en":"Promote a title, attract new members, or let the director identify opportunities.","fr":"Promouvoir un titre, attirer de nouveaux membres ou laisser le directeur identifier les occasions."}'::jsonb),('ui','Number of publications','{"en":"Number of publications","fr":"Nombre de publications"}'::jsonb),('ui','AI generation uses the existing platform credit system. No advertising spend or social publication.','{"en":"AI generation uses the existing platform credit system. No advertising spend or social publication.","fr":"La génération IA utilise les crédits de la plateforme. Aucune dépense publicitaire ni diffusion sociale."}'::jsonb),('ui','Generating campaign','{"en":"Generating campaign","fr":"Génération de la campagne"}'::jsonb),('ui','Generate campaign','{"en":"Generate campaign","fr":"Générer une campagne"}'::jsonb),('ui','Production notes','{"en":"Production notes","fr":"Notes de production"}'::jsonb),('ui','Campaign and drafts saved','{"en":"Campaign and drafts saved","fr":"Campagne et brouillons enregistrés"}'::jsonb),('ui','Accept plan and create drafts','{"en":"Accept plan and create drafts","fr":"Accepter le plan et créer les brouillons"}'::jsonb) on conflict(namespace,source_key) do nothing;